pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    function setUp() public { c = new PrivateBank(address(this)); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount = bound(amount, 0, 1 ether - 1);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();
        assertEq(c.balances(actor), 0);
    }
}
